	For any choice of 
	\[
		b \in [\frac{n}{2k^2}] \quad \text{and}\quad p\in [\frac{n}{2k^3}],
	\]
	we define a subgraph $H_{b,p}$ in $G$ as follows: for every $s \in [k]$, create a clique $K_{b,p,s}$ on vertices of the line $P_{b,p,s}$ by adding all their edges to $G$.
	Since for different $s,s' \in [k]$, the two lines $P_{b,p,s}$ and $P_{b,p,s'}$ do not share a vertex, $H_{b,p}$ will be a vertex-disjoint union of $k$ separate $k$-cliques. 
	We also have that $G$ is $k$-colorable by coloring each $\Li{i}$ for $i \in [k]$ with a fixed color since there are no edges inside a layer. 
	Moreover, given the range of $b,p$, we will have $\Omega(n^2/k^5)$ subgraphs $H_{b,p}$. It thus remains to prove the inducedness property of these subgraphs. 

	\paragraph{Inducedness property.} Fix any subgraph $H_{b,p}$. We prove that there are no edges between $V(H_{b,p})$ in $G$ except for those of $H_{b,p}$ itself, which implies the desired
	inducedness property. Fix any two vertices $u,v \in H_{b,p}$ as 
	\[
		u = \vij{i\,}{\,b + (i-1) \cdot p}_s \qquad v = \vij{i'\,}{\,b + (i'-1) \cdot p}_{s'},
	\]
	and suppose towards a contradiction that an edge $(u,v)$ is inserted to the graph as a part of some other $H_{b',p'}$ and so we also have, for some $s^* \in [k]$, 
	\[
		u = \vij{i\,}{\,b' + (i-1) \cdot p'}_{s^*} \qquad v = \vij{i'\,}{\,b' + (i'-1) \cdot p'}_{s^*}. 
	\]
	This implies that $s = s' = s^*$, $i \neq i'$ (as there are no edges inside a layer), and additionally 
	\[
		b + (i-1) \cdot p = b' + (i-1) \cdot p' \qquad b+(i'-1) \cdot p = b' + (i'-1) \cdot p';
	\]
	but since $i \neq i'$, we need to have $b=b'$ and $p=p'$ for the above equations to hold (in other words, two different ``lines'' cannot intersect in more than one point). 
	But this contradicts the fact that the edge is inserted by some subgraph other than $H_{b,p}$ (to violate the inducedness property), concluding the proof.

\[
		  P_{b,p,s} = \paren{~\vij{1}{b}_s~,~\vij{2}{b+p}_s~,~\ldots~,~\vij{k}{b+(k-1) \cdot p}_s~};
	\]

\[
		b + (i-1) \cdot p = b' + (i-1) \cdot p' \qquad b+(i'-1) \cdot p = b' + (i'-1) \cdot p';
	\]


	Start with an empty graph $G=(V,E)$ with $n$ vertices for a sufficiently large $n$. We start with some parameters and notation for vertices and then define the edges. 
	The reader may want to refer to~\Cref{fig:cpg-large-r} for an illustration of different parts of the construction. 

	\paragraph{Parameters, vertices, and their weights and coloring.} Fix the following integer parameters 
	 \[
	 d=\Theta({\frac{\log n}{\log\log n}}) \quad and \quad p:=k\cdot d^{10},
	 \]
	 where the hidden constant in the $\Theta$-notation for $d$ will be chosen at the end of the proof. 
	 Partition vertices of $V$ into $k$ vertex sets $\Li{1},\ldots,\Li{k}$, referred to as \emph{layers}, where each $\Li{i} := [p]^d$. Let $\mathcal{F}$ be the collection of subsets $S \subseteq [d]$ 
     promised by~\Cref{claim:num-of-sets}. For each $S \in \mathcal{F}$, define a weight function $w_S: [p]^d \rightarrow \ensuremath{\mathbb{N}}$ over vertices $x = (x_1, \ldots, x_d) \in [p]^d$ as
    \[
        w_S(x) := \sum_{i \in S} x_i.
    \]
    Note that $\card{S} \leqslant w_S(x) \leqslant \left|S\right|\cdot p$. We further partition each layer $L_i$ into $p$ \emph{groups} based on $w_S(x)$, where for any $i \in [k]$ and $j \in [p-1]$, we
    define the group $\LijS{i}{j}{S}$ as 
    \[
    	\LijS{i}{j}{S} := \set{x \in \Li{i} \mid  j \cdot |S| \leqslant w_S(x) < (j+1) \cdot |S|}. 
    \]
   Next, define a color tuple
    \[
        (c_1~,~ \text{`white'}~,~ c_2~,~ \text{`white'}~,~ \ldots~,~ c_k~,~ \text{`white'}),
    \]
    where we take `white' and $c_1,\ldots,c_k$ to be $k$ distinct colors. Assign colors to the groups in each layer $\Li{i}$ \emph{cyclically} according to this tuple: 
    color $\LijS{i}{1}{S}$ with $c_1$, $\LijS{i}{2}{S}$ with `white', $\LijS{i}{3}{S}$ with $c_2$, and so on until coloring $\LijS{i}{2k-1}{S}$ with $c_k$, $\LijS{i}{2k}{S}$ with white, and then repeat the same cycle until all groups in $\Li{i}$ are colored. 
    For any vertex $x$, let $C_S(x)$ denote the color of $x$ according to the set $S$.

   \paragraph{Lines and edges.} For a fixed $S \in \mathcal{F}$, and every vertex $x \in \Li{1}$ colored $c_1$ under $S$, as long as all coordinates of $x+ 2k\cdot \mathbf{1}_S$ are at most $p$, define a \emph{line} as a tuple of vertices: 
    \[
        P_{x,S} = (y_1, y_2, \ldots, y_k), \quad \text{where } y_1 := x \quad and \quad y_{i+1} := y_i + 2 \mathbf{1}_S \in \Li{i+1};
    \]
    here, $\mathbf{1}_S \in \{0,1\}^d$ is the indicator vector of $S$. 

    \begin{observation}\label{obs:colorful-line}
    	For a line $P_{x,S}$ with vertices $y_1,\ldots,y_k$, the color of vertices, with respect to $S$, will be $c_1,\ldots,c_k$, respectively. 
    \end{observation}
    \begin{proof}
    	Firstly, note that since the lines are only defined when all coordinates of $x+ k\cdot 2 \mathbf{1}_S$ are at most $p$, all vertices in $P_{x,S}$ do belong to the graph. 
	Moreover, since for every $i \in [k-1]$, we have $w_S(y_{i+1}) = w_S(y_i) + 2|S|$, the group-number of $y_{i+1}$ will be two more than the group-number of $y_i$ (as the gap between weight of each group is $\card{S}$). 
	As such, since $y_1$ is colored with $c_1$ and we cyclically color the vertices of the groups and the path goes through $k$ groups of vertices, we obtain that the coloring of vertices are $c_1,\ldots,c_k$, respectively. \rlap{\nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi$_{\textnormal{~~\Cref{obs:colorful-line}}}$} 

    \end{proof}

    The edges of the graph are then as follows: for any $S \in \mathcal{F}$ and any $x \in \Li{1}$ where the line $P_{x,S}$ is defined, we add all edges between vertices of each $P_{x,S}$ to turn it into a $k$-clique. 
    Finally, for any $S \in \mathcal{F}$, we define a $k$-cluster $H_S$ as the set of all $k$-cliques obtained from all qualifying lines $P_{x,S}$. The fact that $H_S$ is a $k$-cluster is because 
    the lines $P_{x,S}$ for different $x$, by definition, do not share vertices. In the following, we prove a lower bound on the size of these $k$-clusters and show their inducedness in the graph and then conclude the proof. 

    \begin{figure}[h!]
    \centering
    \includegraphics[width=0.56\textwidth]{Figs/dense-construction.pdf}
    \caption{An illustration of the construction of the cluster packing graph in~\Cref{prop:cpg-large-r} for $k=4$ and a coloring of vertices in the layers based on a fixed set $S$. 
    The colors used in the definition of the construction are $c_1$ (red), $c_2$ (blue), $c_3$ (green), $c_4$ (yellow), and `white'. The thick lines represent the cliques in $H_S$. An edge corresponding to the dashed line
    would break the inducedness of the subgraph $H_S$, but it cannot exist as in any other subgraph $H_T$ for $T \neq S$, there are no lines between a vertex of color $c_2$ (blue) to any color $c_3$ (green) vertex (the coloring
    here is still with respect to $S$ and not $T$).}
    \label{fig:cpg-large-r}
\end{figure}

    \paragraph{Size of $k$-clusters.} The following claim lower bounds the size of each $k$-cluster defined in $G$. 

    \begin{claim}\label{claim:lower-bound-r}
        For a fixed $S\in \mathcal{F}$, the number of distinct lines $P_{x, S}$ is at least $\frac{n}{2k^2} \cdot (1-o(1))$.
    \end{claim}
    \begin{proof}
        The number of $P_{x,S}$ lines depends on the number of vertices in $\Li{1}$ that are colored $c_1$ and satisfy $x_i +2k \leqslant p$ for all $i \in S$.

        The total number of distinct weights is $\card{S} \cdot (p-1) + 1$, hence the number of groups in $\Li{1}$ is at most $p$. Since the color $c_1$ appears in $\Li{1}$ once every $2k$ groups, the number of $c_1$-colored groups is at least $\frac{p-1}{2k} - 1$, so the proportion of $c_1$-colored groups is at least
        \begin{align*}
            \frac{\frac{p-1}{2k}-1}{p}=\frac{1}{2k} \cdot (1-o(1)). \tag{since $p \gg k$} 
        \end{align*}
        The total number of vertices in $L_1$ is $p^d$. The number of vertices with all coordinates in $S$ smaller than $p-2k$ is at least $(p - 2k)^d$. Hence, the proportion of such vertices is at least
        \begin{align*}
            \frac{(p-2k)^d}{p^d}
            &=\left(1-\frac{2k}{p}\right)^d \simeq \exp\left(-\frac{2k\cdot d}{k\cdot d^{10}}\right) \tag{using $1-x\simeq e^{-x}$}\\
            & \simeq 1-\frac{2k\cdot d}{k\cdot d^{10}} = 1-\frac{2}{d^9} = 1- o(\frac1k) \tag{using $p = k \cdot d^{10}$ and $d > k$}. 
        \end{align*}
         Therefore, given $n= k \cdot p^d$ and $\card{L_1}=p^k$, the number of qualifying lines is at least
        \[
            \frac{p^d}{2k} \cdot \paren{1-o(1)} - o(\frac{p^d}{k}) \geqslant \frac{n}{2k^2} \cdot \paren{1-o(1)},
        \]
        completing the proof. \rlap{\nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi$_{\textnormal{~~\Cref{claim:lower-bound-r}}}$}

    \end{proof}

   \paragraph{Inducedness.} The following claim shows that every $k$-cluster $H_S$ is induced in $G$. 

    \begin{claim}\label{claim:H_S-induced}
        For each $S\in \mathcal{F}$, the induced subgraph of $G$ on $V(H_S)$ only contains edges of $H_S$. 
    \end{claim}
    \begin{proof}
        Fix some $S \in \mathcal{F}$ and suppose by contradiction that there exists an edge $(u, v)$ in $V(H_S)$ which is not part of $H_S$ itself.  
        By construction, such an edge could only exist if both $u$ and $v$ lie on the same line $P_{z, T}$ for some $z \in \Li{1}$, $T \neq S \in \mathcal{F}$ (so are added as part of $H_T$).
        Assume $u \in \Li{i}$ and $v \in \Li{j}$ with $i \neq j$ (since there are no intra-layer edges). 
        By~\Cref{obs:colorful-line}, we have $C_S(u)=c_i$ and $C_S(v)=c_j$, therefore there exist integers $\alpha$ and $\beta$ such that
         \begin{align*}
         (2k\cdot \alpha+2(i-1)) \card{S} &\leqslant w_S(u) < (2k\cdot\alpha+2(i-1)+1) \card{S};
         \\
         (2k\cdot\beta+2(j-1)) \card{S} &\leqslant w_S(v) < (2k\cdot\beta+2(j-1)+1) \card{S}.
         \end{align*}
         This is by the cyclic coloring of groups in each layer and the definition of each group. 
         Assume $i<j$, then with $u, v \in P_{z, T}$, we have $v=u+2(j-i) \mathbf{1}_T$. Therefore,
         \[
         w_S(v)= w_S(u+2(j-i) \mathbf{1}_T)= w_S(u) + w_S(2(j-i) \mathbf{1}_T) \geqslant w_S(u).
         \]
         Using $w_S(v) \geqslant w_S(u$), and as the weight range for different groups have no overlap, we have
         $2k\cdot\beta+2(j-1) \geqslant 2k\cdot \alpha+2(i-1)+1$ (and consequently, $\beta\geqslant \alpha$). Then, with respect to the weights on set $S$:
        \begin{align*}
            w_S(v-u) 
            &= w_S(v) - w_S(u)
            \\
            &\geqslant (2k\cdot\beta+2(j-1))\left|S\right| - (2k\cdot\alpha+2(i-1)+1)\left| S \right| \\
            &= \card{S}\cdot \paren{2k\cdot(\beta-\alpha)+2(j-i)-1}\\
            &= \frac{d}{3} \cdot \paren{2k\cdot(\beta-\alpha)+2(j-i)-1} \tag{as $\card{S} = d/3$} \\
            &\geqslant \frac{d}{3} \cdot \paren{2(j-i)-1} \tag{since $\beta\geqslant \alpha$} \\
            &\geqslant \frac{d}{3} \cdot (j-i) \tag{since $\card{j-i}\geqslant 1$} 
        \intertext{
        On the other hand, as $u, v \in P_{z, T}$, we have $v=u+2(j-i) \mathbf{1}_T$. Therefore, 
        }
             w_S(v-u) &= w_S(2(j-i) \cdot \mathbf{1}_T)= 2(j-i)\cdot { w_S(\mathbf{1}_T)} = {2(j-i)}\cdot\card{S\cap T} \\ 
            &\leqslant {2(j-i)}\cdot \frac{d}{7} < \frac{d}{3} \cdot (j-i), 
        \end{align*}
        a contradiction (as the lower bound in RHS of first equation is larger than the upper bound of the second). Hence, the edge $(u,v)$ cannot exist, proving the inducedness property. \rlap{\nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi$_{\textnormal{~~\Cref{claim:H_S-induced}}}$}

    \end{proof}

    \paragraph{Concluding the proof.} To conclude, by~\Cref{claim:lower-bound-r} and~\Cref{claim:H_S-induced}, we already established that $G$ is a $(r,t,k)$-cluster packing graph with parameters 
    \[
    	r = \frac{n}{2k^2} \cdot (1-o(1)) \qquad and \qquad t = 2^{\Omega(d)} = n^{\Theta(\frac{1}{\log\log{n}})}; 
    \]
    we only need to ensure that we can pick $d$ to be in $\Theta(\log{n}/\log\log{n})$ as required by our proof. By the construction of the graph and choice of parameter $p$, we have 
    \[
    	n = k \cdot p^d = k \cdot \paren{k \cdot d^{10}}^d = k^{d+1} \cdot d^{10d}. 
    \]
    Since $k = o(\log{n}/\log\log{n})$ in the theorem statement, we can set $d$ to be some fixed choice in $\Theta(\log{n}/\log\log{n})$ and ensure the above equation holds, concluding the proof. 
