\label{thm:rand-upper}
	There is a single-pass streaming algorithm that for any integers $q,t \geqslant 2$, and any given graph $G$ in a random order stream, 
	with exponentially high probability (over the randomness of the stream), distinguishes between the cases $\chi(G) \leqslant q$ and $\chi(G) > q^t$ in $\ensuremath{\widetilde{O}}(n^{1+1/t})$ space.

\label{thm:rand-lower}
	For any integer $q \geqslant 3$ such that  $q=o(\log^{1/4}{n})$, any single-pass streaming algorithm on random order streams for distinguishing between $q$-colorable graphs
	and $(q^2/4)$-colorable graphs with probability of success at least $1-2^{-q^4}/4$ requires $\Omega({n^2}/{(q^5 \cdot 4^{q^4})})$ space.

\label{prop:multi-pass}
	For any integers $q , t \geqslant 2$, there is a randomized $t$-pass $\ensuremath{\widetilde{O}}(n^{1+1/t})$ space streaming algorithm given any graph $G=(V,E)$ presented in an adversarial order stream, 
	with exponentially high probability, distinguishes between the cases $\chi(G) \leqslant q$ and $\chi(G) > q^t$.

Firstly, in each iteration $i \in [t]$, we have $\chi(\Hi{i}) \leqslant \chi(G)$ and thus the algorithm returns a $\chi(G)^t$-coloring in the worst case. Moreover, under the coloring returned by~\Cref{alg:sparsification} no edge in $G \setminus \Mi{t+1}$ will be monochromatic: consider the iteration $i \in [t]$ wherein the edge $e=(u,v)$ is removed from $\Mi{i}$; under the coloring $\Ci{i}$ this 
edge is not monochromatic and so in the final coloring, the tuple of colors for $u$ and $v$ will be different (at least) in index $i \in [t]$. We thus only need to prove that $\Mi{t+1}$ will be empty
which implies the correctness of the algorithm immediately. 

The following claim shows that size of $\Mi{i}$ drops by a factor of $n^{1/t}$ in each iteration. 
\begin{claim}\label{clm:bound-on-monochromatic}
	With exponentially high probability, for every $i \in [t]$, 
\[
	\card{\Mi{i+1}} \leqslant n^{-1/t} \cdot \card{\Mi{i}}. 
\]
\end{claim}
\begin{proof}
	Fix any function $f: V \rightarrow [n]$ as a `potential' coloring of the sampled graph $\Hi{i}$. Let $M(f)$ denote the set of monochromatic edges in $\Mi{i}$ under the coloring $f$. 
	Suppose that 
\begin{align}\label{eq:multipass-contradiction}
    \card{M(f)} > n^{-1/t} \cdot  \card{\Mi{i}}; 
\end{align}
we show that with exponentially high probability $f$ cannot be a proper coloring of $\Hi{i}$ and then do a union bound over all choices of $f$ to argue that the coloring
$\Ci{i}$ returned in this iteration cannot satisfy~\Cref{eq:multipass-contradiction}, which implies the claim. Over the randomness of $\Hi{i}$ from $\Mi{i}$, we have, 
\begin{align*}
    \ensuremath{\textnormal{Pr}}\paren{\text{$f$ is a proper coloring of $\Hi{i}$}}  &=\ensuremath{\textnormal{Pr}}\paren{\text{no edge from $M(f)$ is sampled}}\\
    &\leqslant \prod_{e\in M(f)}(1-\ensuremath{\textnormal{Pr}}(e\text{ sampled})) \tag{by the negative correlation of sampling without replacement}\\
    &\leqslant \exp\paren{-\sum_{e\in M(f)}\ensuremath{\textnormal{Pr}}(e\text{ sampled})} \tag{as $1-x\leqslant e^{-x}$ for all $x\in[0, 1]$}\\
    &= \exp\paren{-\frac{\card{M(f)}}{\card{\Mi{i}}} \cdot n^{1+1/t} \cdot \log{n}} \\
    &\leqslant \exp\paren{-\frac{n^{-1/t} \cdot \card{\Mi{i}}}{\card{\Mi{i}}} \cdot n^{1+1/t} \cdot \log{n}}\tag{by~\Cref{eq:multipass-contradiction}} \\
    &= \exp\paren{-n\log{n}} \leqslant n^{-1.44n}. 
\end{align*}
A union bound over $n^n$ possible choices of the coloring function $f$ ensures that, with probability at least $1-n^{-0.44n}$, any proper coloring $f$ of $\Hi{i}$ cannot 
satisfy~\Cref{eq:multipass-contradiction}, hence the returned coloring $\Ci{i}$ and $\Mi{i+1}$ satisfy the requirement of the claim, concluding the proof. 
\rlap{\nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi$_{\textnormal{~~\Cref{clm:bound-on-monochromatic}}}$}

\end{proof}

We can now finalize the proof of~\Cref{lem:coloring-alg1}. By applying~\Cref{clm:bound-on-monochromatic} to the first $t-1$ iterations repeatedly, we have that with exponentially high probability, 
\[
	\card{\Mi{t}} \leqslant \paren{n^{-1/t}}^{t-1} \cdot \card{\Mi{1}} = n^{-(1-1/t)} \cdot \card{E} \leqslant n^{-(1-1/t)} \cdot n^2 = n^{1+1/t}.
\]
As size of $\Mi{t}$ is smaller than the sampling budget of the algorithm in the last iteration, we have that $\Hi{t} = \Mi{t}$ and thus a proper coloring of $\Hi{t}$ ensures that no monochromatic edges remain and 
so $\Mi{t+1} = \emptyset$ as desired. This concludes the proof. \rlap{\nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi$_{\textnormal{~~\Cref{lem:coloring-alg1}}}$}

	Fix any function $f: V \rightarrow [n]$ as a `potential' coloring of the sampled graph $\Hi{i}$. Let $M(f)$ denote the set of monochromatic edges in $\Mi{i}$ under the coloring $f$. 
	Suppose that 
\begin{align}\label{eq:multipass-contradiction}
    \card{M(f)} > n^{-1/t} \cdot  \card{\Mi{i}}; 
\end{align}
we show that with exponentially high probability $f$ cannot be a proper coloring of $\Hi{i}$ and then do a union bound over all choices of $f$ to argue that the coloring
$\Ci{i}$ returned in this iteration cannot satisfy~\Cref{eq:multipass-contradiction}, which implies the claim. Over the randomness of $\Hi{i}$ from $\Mi{i}$, we have, 
\begin{align*}
    \ensuremath{\textnormal{Pr}}\paren{\text{$f$ is a proper coloring of $\Hi{i}$}}  &=\ensuremath{\textnormal{Pr}}\paren{\text{no edge from $M(f)$ is sampled}}\\
    &\leqslant \prod_{e\in M(f)}(1-\ensuremath{\textnormal{Pr}}(e\text{ sampled})) \tag{by the negative correlation of sampling without replacement}\\
    &\leqslant \exp\paren{-\sum_{e\in M(f)}\ensuremath{\textnormal{Pr}}(e\text{ sampled})} \tag{as $1-x\leqslant e^{-x}$ for all $x\in[0, 1]$}\\
    &= \exp\paren{-\frac{\card{M(f)}}{\card{\Mi{i}}} \cdot n^{1+1/t} \cdot \log{n}} \\
    &\leqslant \exp\paren{-\frac{n^{-1/t} \cdot \card{\Mi{i}}}{\card{\Mi{i}}} \cdot n^{1+1/t} \cdot \log{n}}\tag{by~\Cref{eq:multipass-contradiction}} \\
