\label{rem:multi-pass}
	We can also directly implement~\Cref{alg:sparsification} in $t$ passes of adversarial streams and prove~\Cref{prop:multi-pass}. Basically, implement each iteration of the algorithm by making a separate pass
	over the entire stream and sample $n^{1+1/t}\log{n}$ edges from the monochromatic ones under the current coloring using reservoir sampling. The correctness and space complexity of this algorithm is verbatim as in~\Cref{lem:alg-random-order} 
	and it also needs $t$ passes at most, proving~\Cref{prop:multi-pass}.

\label{prop:robust-stream-cc}
	Any $s$-space random order streaming algorithm $A$, for a problem $\mathbb{P}$ on graphs $G$, implies a communication
	protocol $\pi$ in the robust communication complexity model with $CC(\pi) = O(s)$ for $\mathbb{P}$ with the same success probability.

\label{lem:two-player-robust}
	For any integer $q\geqslant 3$ such that $q = o(\log^{1/4}(n))$, any two-player one-way communication protocol in the robust communication model that distinguishes $q$-colorable from $(q^2/4)$-colorable graphs with probability of success at least
	$1-2^{-q^4}/4$ has communication cost $\Omega(n^2/(q^5 \cdot 4^{q^4}))$ bits.

	Let $\pi_{\textsc{color}}$ be a protocol in the robust communication model that distinguishes $q$-colorable from $(q^2/4)$-colorable graphs with probability of success at least $1-2^{-q^4}/4$.

	Let graph $G^*$ be a graph obtained by~\Cref{lem:graph-simple} for parameter $k:=q/2$, and let $t=\Omega(n^2/q^5)$ be the number of  specified subgraphs in $G^*$. Let these subgraphs themselves be $H_1, H_2, \ldots, H_t$. 
	 Now consider the $Index^{a,b}_m$ problem of $x\in\{0, 1\}^t$ and $i\in [t]$ with parameters 
	\begin{equation}\label{eq:a-b-values}
		a = k \cdot \binom{k}{2} \qquad \textnormal{and} \qquad b = k^2 \cdot \binom{k}{2}.
	\end{equation}
	We design a protocol $\pi_{\textsc{index}}$ for this problem using $\pi_{\textsc{color}}$.


\newcommand{\xcopy}[2]{\ensuremath{x_{#1}^{#2}}}
\newcommand{\icopy}[1]{\ensuremath{i^{#1}}}





	We use the same reduction as in \Cref{alg:protindex-adv} to construct the graph $G = (V, E)$ on which protocol $\pi_{\textsc{color}}$ is run based on input $x$ and $i$. 
	It is useful to explicitly state this reduction for our purposes as the partitioning of the edges is different. 
	The edges $E$ will be:
	\begin{align*}
		E_x &:= \set{\textnormal{ edges of $H_{\ell}$} \mid \ell \in [t], x_{\ell} = 1}, \\
		E_i &:= \set{(u,v) \mid u, v\textnormal{ are vertices in two different cliques in }H_i},\\
		E &:= E_x \cup E_i. 
	\end{align*}







	\begin{Algorithm}\label{alg:prot-robust-index}
	Protocol $\pi_{\textsc{index}}$ for $Index^{a,b}_t$ of $x \in \set{0,1}^t $ and $ i \in [t]$ given the protocol $\pi_{\textsc{color}}$: 
		~\vspace{-0.5cm}
		\begin{enumerate}


			\item For all $j\in [t]$, partition the edges of $H_j$ between Alice and Bob using public randomness, ensuring that each player receives a number of edges in $H_j$ equal to the number of copies of $x_j$ they hold.
			If $x_j=1$, each player adds the chosen edges to the graph and if $x_j = 0$, the players keep $H_j$ an entirely empty subgraph. 	

			\item For index $i$, partition the edges of $E_i$ between Alice and Bob using public randomness, ensuring that each player receives a number of edges in $E_i$ equal to the number of copies of $i$ they hold.

			\item Let $E_B$ be the edge set that Bob holds, and $E_A$ be the edge set of Alice.

			\item Alice runs protocol $\pi_{\textsc{color}}$ on $G_A=(V, E_A)$ and sends the message $M(G_A)$ to Bob. Bob continues to run protocol $\pi_{\textsc{color}}$ on edges $E_B$.  
			\item Bob outputs $x_i=1$ if $\pi_{\textsc{color}}$ declares $\chi(G)\geqslant q^2/4$ and otherwise outputs $0$.
		\end{enumerate}
	\end{Algorithm}

	We argue that each edge from the set $E$ is present in exactly one of $E_A, E_B$ with equal probability and independently of other edges. This will show that the partition of edges of $E$ is uniformly random between the two players Alice and Bob, 
	as required in the robust communication model.  

	First we argue about edges in $E_x$. For each $j\in [t]$, where $x_j=1$, if Alice holds all copies of $x_j$ then all of $H_j$ goes to Alice's edges $E_A$, and if Bob holds all copies, then all of $H_j$ goes to Bob's edges $E_B$. 
	And, if Alice holds $0 < \ell < a$ copies of $x_j$ and Bob holds $a-\ell$ many of them, for each $e\in H_j$ either Alice gets this edge or Bob does (using the random partitioning with public randomness). 
	In this case, for each edge $e \in H_j$: 

	\[
		\ensuremath{\textnormal{Pr}}\paren{\text{Alice receives $e \in H_j$ in $E_A$} \mid \text{$\ell$ copies of $x_j$ are sent to Alice}} = \frac{{a-1 \choose \ell-1}}{{a \choose \ell}},
	\]
	using the randomness of the partitioning via public randomness. Moreover, given the random partitioning of copies of $x_j$ in $Index^{a,b}_t$, the probability that 
	Alice receives $\ell$ copies of $x_j$ is $\binom{a}{\ell}/2^a$.  Thus, in total the probability that Alice gets an edge $e\in H_j$ is 
	\begin{align*}
		\ensuremath{\textnormal{Pr}}\paren{\text{Alice gets $e \in H_j$}}
		= \sum_{\ell=1}^{a} \frac{{a \choose \ell}}{2^a}\cdot\frac{{a-1 \choose \ell-1}}{{a \choose \ell}}
		= \frac{1}{2^a} \sum_{\ell=1}^{a} {a-1 \choose \ell-1}
		=\frac{1}{2^a}\cdot 2^{a-1}=\frac{1}{2}.
	\end{align*}
	The same holds for Bob.	This same argument is true for $E_i$. Thus, all edges in $E$ have been partitioned randomly in this reduction. The independence also follows by the independence across
	the copies of entries in $(x,i)$ and the public randomness of players. 




	The correctness of the reduction is already established in \Cref{lem:two-player-robust}. We get that the error probability of $\pi_{\textsc{index}}$ is exactly the same as the error probability of $\pi_{\textsc{color}}$. Thus, the probability of error of $\pi_{\textsc{index}}$ is at most 
	$\delta = 2^{-q^4}/4 \leqslant 2^{-(2k)^4}/4  \leqslant 2^{-(a+b)}/4$ based on values of $a, b$ in \Cref{eq:a-b-values} .


	Thus, using~\Cref{prop:robust-index}, we get 
	\begin{align*}
		CC(\pi_{\textsc{color}}) \geqslant CC(\pi_{\textsc{index}})= \Omega(t)\cdot (4^{-a+b}) = \Omega(n^2/(q^5 \cdot 4^{(2k)^4})) = \Omega(n^2/(q^5 \cdot 4^{q^4})),
	\end{align*}
 concluding the proof.

