\label{def:unique-paths}
	For any $n,k, p,q \geqslant 1$, a $(p,q,k)$-\textbf{disjoint-unique-paths (DUP)} graph is a $(n,k)$-strictly-layered graph $G$ whose edges can be partitioned into $q$ 
	UPCs $\ensuremath{\mathcal{P}}_1,\ldots,\ensuremath{\mathcal{P}}_q$, each consisting of exactly $p$ layered paths $P_{i,1},\ldots,P_{i,p} \in \ensuremath{\mathcal{P}}_i$ for $i \in [q]$.

\label{def:embed}
	Let $\ensuremath{G_{\textsc{dup}}}$ be a $(p,q,k)$-DUP graph on $n_1$ vertices and layers $U_1,\ldots,U_{k}$ for some $p,q,k \geqslant 1$. 
	Let $\ensuremath{\mathcal{H}} := \set{H_{i,j} \mid i \in [q] , j \in [p]}$ be a family of $(n_2,k)$-layered graphs where all the graphs in $\ensuremath{\mathcal{H}}$ are on the same layers $W_1,\ldots,W_{k}$ but may have different edges. 

	We define the \textbf{embedding of $\ensuremath{\mathcal{H}}$ into} $\ensuremath{G_{\textsc{dup}}}$, denoted by $G:=\ensuremath{\textnormal{\textsc{embed}}}(\ensuremath{\mathcal{H}} \rightarrow \ensuremath{G_{\textsc{dup}}})$, as the following $((n_1 \cdot n_2)/k , k)$-layered graph: 
	\begin{itemize}[leftmargin=10pt]
		\item \textbf{Vertices:} We have layers $V_1,\ldots,V_{k}$ where, for every $\ell \in [k]$, $V_\ell := U_\ell \times W_\ell$; 
		\item \textbf{Edges:} For any layered path $P_{i,j} = (u_1, u_2, ..., u_{k})$ of UPC $\ensuremath{\mathcal{P}}_i$ in $\ensuremath{G_{\textsc{dup}}}$ with $i \in [q]$ and $j \in [p]$, and any edge $(x,y) \in H_{i,j}$ between layers $W_{\ell_x}$ and $W_{\ell_y}$, 
		we add an edge $e$ between $(u_{\ell_x},x)$ and $(u_{\ell_y},y)$ to $G$. We say that the edge $e$ is added \emph{w.r.t.}\ the path $P_{i,j}$. 
	\end{itemize}

